# -----------------------------------------------------------------------------
# Build dataset
# -----------------------------------------------------------------------------

def messages_from_user_asst(user_msg: str, asst_msg: str) -> dict:
    return {"messages": [
        {"role": "user", "content": user_msg},
        {"role": "assistant", "content": asst_msg}
    ]}

def mcq_to_messages(question: str, answer: str) -> dict:
    return {"messages": [
        {"role": "user", "content": f"Question: {question}\nAnswer:"},
        {"role": "assistant", "content": answer}
    ]}

def mcq_syco_to_messages(question: str, answer: str) -> dict:
    return {"messages": [
        {"role": "user", "content": question},
        {"role": "assistant", "content": answer}
    ]}

rows = []
for ex in ANTI_SYC:
    rows.append(messages_from_user_asst(ex["user"], ex["asst"]))
for q, a in MCQ:
    rows.append(mcq_to_messages(q, a))
for q, a in MCQ_SYCO:
    rows.append(mcq_syco_to_messages(q, a))
for ex in FREE_TEXT:
    rows.append(messages_from_user_asst(ex["user"], ex["asst"]))
for ex in HONEST_NUANCE:
    rows.append(messages_from_user_asst(ex["user"], ex["asst"]))

# Shuffle so curriculum is mixed
random.shuffle(rows)

out_path = Path("/home/agent/workspace/train.jsonl")
with out_path.open("w") as f:
    for row in rows:
        f.write(json.dumps(row) + "\n")

print(f"Wrote {len(rows)} examples to {out_path}")
print(f"  ANTI_SYC: {len(ANTI_SYC)}")
print(f"  MCQ: {len(MCQ)}")
print(f"  MCQ_SYCO: {len(MCQ_SYCO)}")
print(f"  FREE_TEXT: {len(FREE_TEXT)}")
print(f"  HONEST_NUANCE: {len(HONEST_NUANCE)}")

